// TH15 Stage 6 道中 第4波 (th15_s6_w04)
// 源: st06.ecl.txt:674-697 MainSub03 排程; 依赖 Phantom04(1158-1177)/Phantom04_at(1179-1323),
//     Phantom05(1325-1344)/Phantom05_at(1346-1395)。
// 五只 Phantom04(间90) 接五只 Phantom05(间180)，全部在 (0,0) 创建，弹由绝对 offset 发射
// (源 etOffsetAbs)，因此所有弹共享同一全局 offset 弹源区域，与本敌实际位置无关。
// 源弹型: type8 -> TH15_RICE(color6), type16 -> TH15_STAR_R(color2)。
// 出生 ANIM(etEx type2 a1) 整体省略；按已批口径保留 position -= 4*velocity 退位移。

const TIME_LIMIT: int = 2144;
const OPENING_BUFFER: int = 120;

const TH15_RICE: int = 480;
const TH15_STAR_R: int = 608;

// RANDF2 (-9987) 均匀 [-1,1)；用 (rand-32768)/32768 的有符号定点形式。
// RANDF  (-9999) 均匀 [0,1) = signed/2 + 0.5。
// 源先取 RANDF2 再取 RANDF；本卡保持此顺序与次数。

// Phantom04_at: 每组的 10 连发，1px/帧间距，角度固定向下(源 etAim=1 固定扇形, etAngle=pi/2)，
// 速度 4.0(单层)，从绝对 offset 出生；ANIM 退位移令实际出生点上移 4*4=16px。
async sub p04_fire() {
    var a: fx = 32fx;        // %A = 32，随每组 +1 直到 64
    var b: int = 15;         // $B = 15，随每组 -1 直到 0（等待帧）
    var easy: int = 0;
    if global(GVAR_RANK) == RANK_EASY { easy = 1; }
    // 外层循环对应源 $C=10000 的组循环；窗口 2020 帧远小于其耗尽时间，故用 loop 直到段结束。
    loop {
        // 一组外层循环 = 7 个 x 基准 (源 408/1088/.../4784 段)
        for k in 0..7 {
            var base: fx = 0fx;      // 源 _f(0)
            if k == 1 { base = 128fx; }
            if k == 2 { base = -128fx; }
            if k == 3 { base = 192fx; }
            if k == 4 { base = -192fx; }
            if k == 5 { base = 64fx; }
            if k == 6 { base = -64fx; }
            if easy == 1 { wait(15); }   // 源 !E wait(15) 每组前额外等待
            wait(b);                     // 源 wait($B)
            // 源 etOffsetAbs(0, RANDF2*32 + base, RANDF*A)
            var u2: fx = ((rand(65536) - 32768) as fx) / 32768;
            var v: fx = ((rand(65536) - 32768) as fx) / 32768;
            var ox: fx = u2 * 32fx + base;
            var oy: fx = (v / 2fx + 0.5fx) * a;
            for i in 0..10 {             // $D=10 次 etOn
                _ = fire(TH15_RICE, 6, ox, oy - 16fx, 4fx, 90deg, none, none);
                wait(1);
            }
            if a < 64fx { a = a + 1fx; } // 源 %A 递增(上限64)
            if b > 0 { b = b - 1; }      // 源 $B 递减(下限0)
        }
    }
}

// Phantom05_at: 每轮一发，从绝对 offset 出生并自机狙(源 etAim=0, etAngle=0)。
// %A 恒为 32；速度与两处等待按难度分支。
async sub p05_fire() {
    var speed: fx = 3.5fx;
    var w1: int = 60;
    var w2: int = 8;
    var r: int = global(GVAR_RANK);
    if r == RANK_NORMAL { speed = 3.5fx; w1 = 30; w2 = 1; }
    if r == RANK_HARD   { speed = 4fx;   w1 = 20; w2 = 1; }
    if r >= RANK_LUNATIC { speed = 5.5fx; w1 = 10; w2 = 1; }
    loop {
        wait(w1);                    // 源第一段难度等待
        // 源 etOffsetAbs(0, RANDF2*192, RANDF*32)
        var u2: fx = ((rand(65536) - 32768) as fx) / 32768;
        var v: fx = ((rand(65536) - 32768) as fx) / 32768;
        var ox: fx = u2 * 192fx;
        var oy: fx = (v / 2fx + 0.5fx) * 32fx;
        // 自机狙从实际出弹口(offset点)取角
        var ang: angle = atan2($player_y - oy, $player_x - ox);
        // ANIM 退位移：沿弹向后退 4*speed
        var rx: fx = ox - 4fx * speed * cos(ang);
        var ry: fx = oy - 4fx * speed * sin(ang);
        _ = fire(TH15_STAR_R, 2, rx, ry, speed, ang, none, none);
        wait(w2);                    // 源第二段难度等待
    }
}

// Phantom04 本体: setHurtbox(28,28)->r14, setHitbox(16,16)->r8；实敌无敌常驻，异步起发弹任务。
async sub p04_main() {
    set_invuln(65535);
    set_hitbox(8fx);
    set_hurtbox(14fx);
    spawn p04_fire();
    loop { wait(1); }
}

async sub p05_main() {
    set_invuln(65535);
    set_hitbox(8fx);
    set_hurtbox(14fx);
    spawn p05_fire();
    loop { wait(1); }
}

// MainSub03: 卡帧 120 = 源帧 0；其后按源排程 5x90 + 5x180 创建。
async sub pattern() {
    wait(OPENING_BUFFER);
    wait(90);
    _ = spawn_enemy(0fx, 0fx, 120, 0, 1000, 0, p04_main);
    wait(90);
    _ = spawn_enemy(0fx, 0fx, 120, 0, 1000, 0, p04_main);
    wait(90);
    _ = spawn_enemy(0fx, 0fx, 120, 0, 1000, 0, p04_main);
    wait(90);
    _ = spawn_enemy(0fx, 0fx, 120, 0, 1000, 0, p04_main);
    wait(90);
    _ = spawn_enemy(0fx, 0fx, 120, 0, 1000, 0, p04_main);
    wait(180);
    _ = spawn_enemy(0fx, 0fx, 120, 0, 1000, 0, p05_main);
    wait(180);
    _ = spawn_enemy(0fx, 0fx, 120, 0, 1000, 0, p05_main);
    wait(180);
    _ = spawn_enemy(0fx, 0fx, 120, 0, 1000, 0, p05_main);
    wait(180);
    _ = spawn_enemy(0fx, 0fx, 120, 0, 1000, 0, p05_main);
    wait(180);
    _ = spawn_enemy(0fx, 0fx, 120, 0, 1000, 0, p05_main);
    // MainSub03 结束后 670 帧(源帧 2020)→ MainFront:512-513 enmKillAll / etClear(640)。
    wait(670);
    kill_all_enemies(KILL_SILENT);
    clear_bullets_at(0fx, 0fx, 640fx, 0);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
